import{_ as s,a as t,c as a,ac as i}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"Kubernetes 架构与 API","description":"控制平面、节点、API 请求与声明式协调机制","frontmatter":{"title":"Kubernetes 架构与 API","description":"Kubernetes 控制面、节点组件、声明式 API、控制循环和请求链路详解","sources":[{"repository":"TeamDocs","file":"docs/engineering/kubernetes/02-architecture-and-api.md"}],"showdocs":{"topics":[{"id":"kubernetes","title":"Kubernetes","link":"/topics/kubernetes/"},{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Kubernetes 系统教程","summary":"控制平面、节点、API 请求与声明式协调机制","status":"active","related":[{"title":"Kubernetes 操作与命令","link":"/systems/kubernetes/plus/ecosystem/kubernetes-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储","link":"/systems/kubernetes/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · 按 Pod、Service 与端点定位故障至Pod 运行但服务不可达的复盘","link":"/systems/kubernetes/troubleshooting-part-02","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · Kubernetes 排障手册","link":"/systems/kubernetes/troubleshooting-part-01","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes：部署配置、服务身份与持久卷","link":"/systems/kubernetes/plus/practice/application","kind":"实践","scope":"general","audience":"general"}],"prev":{"text":"Kubernetes 环境、版本与学习实验","link":"/systems/kubernetes/setup"},"next":{"text":"Kubernetes 清单：对象结构、身份与字段所有权","link":"/systems/kubernetes/manifests"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Kubernetes 环境、版本与学习实验","link":"/systems/kubernetes/setup"},"next":{"text":"Kubernetes 清单：对象结构、身份与字段所有权","link":"/systems/kubernetes/manifests"}},"headers":[],"relativePath":"systems/kubernetes/plus/subjects/02-architecture-and-api.md","filePath":"systems/kubernetes/plus/subjects/02-architecture-and-api.md"}'),n={name:"systems/kubernetes/plus/subjects/02-architecture-and-api.md"};function l(r,e,d,p,o,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="kubernetes-架构与-api" tabindex="-1">Kubernetes 架构与 API <a class="header-anchor" href="#kubernetes-架构与-api" aria-label="Permalink to &quot;Kubernetes 架构与 API&quot;">​</a></h1><h2 id="集群组成" tabindex="-1">集群组成 <a class="header-anchor" href="#集群组成" aria-label="Permalink to &quot;集群组成&quot;">​</a></h2><p>Kubernetes 集群由控制面和工作节点组成。控制面管理全局期望状态，工作节点运行 Pod。</p><table tabindex="0"><thead><tr><th>组件</th><th>主要职责</th><th>生产关注点</th></tr></thead><tbody><tr><td>kube-apiserver</td><td>暴露 REST API，认证、鉴权、准入、校验和对象读写入口</td><td>多副本、负载均衡、证书、审计、延迟与限流</td></tr><tr><td>etcd</td><td>保存 Kubernetes API 状态的强一致键值存储</td><td>奇数成员、低延迟磁盘、快照、压缩、碎片整理和加密</td></tr><tr><td>kube-scheduler</td><td>为未绑定 Pod 过滤与评分节点，写入绑定结果</td><td>调度延迟、Pending Pod、扩展插件和高可用</td></tr><tr><td>kube-controller-manager</td><td>运行 Deployment、Node、Job 等内置控制器</td><td>Leader Election、工作队列、API 限流</td></tr><tr><td>cloud-controller-manager</td><td>对接云节点、路由、负载均衡器等</td><td>云权限、配额、版本兼容；本地集群可能没有</td></tr><tr><td>kubelet</td><td>在单个节点实现 PodSpec，管理探针、挂载和容器生命周期</td><td>节点资源、证书、CRI、重启和驱逐</td></tr><tr><td>容器运行时</td><td>通过 CRI 拉取镜像、创建 Sandbox 与容器</td><td>通常为 containerd/CRI-O；Kubernetes 不直接使用 Docker Engine</td></tr><tr><td>kube-proxy</td><td>实现 Service 数据面规则</td><td>iptables、IPVS 或 nftables 模式；也可能被 eBPF 数据面替代</td></tr><tr><td>CNI 插件</td><td>实现 Pod 网络、IPAM，部分实现 NetworkPolicy</td><td>地址容量、MTU、路由、策略和可观测性</td></tr><tr><td>CSI 插件</td><td>动态制备、挂载、扩容、快照存储</td><td>拓扑、配额、故障域和数据保护</td></tr></tbody></table><p>Kubernetes 的可移植性来自标准 API 及 CRI、CNI、CSI 等接口，但“同一 YAML 在所有集群行为完全相同”并不成立。LoadBalancer、默认 StorageClass、Ingress/Gateway Controller、网络策略和云身份都依赖具体环境。</p><h2 id="声明式控制循环" tabindex="-1">声明式控制循环 <a class="header-anchor" href="#声明式控制循环" aria-label="Permalink to &quot;声明式控制循环&quot;">​</a></h2><p>控制器反复执行“观察 → 比较 → 行动”：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户/自动化 → API Server → etcd</span></span>
<span class="line"><span>                  ↑          ↓</span></span>
<span class="line"><span>                  └── 控制器观察实际状态</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span>                    创建/更新对象</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span>              Scheduler → kubelet → 运行时/CNI/CSI</span></span></code></pre></div><p>关键概念：</p><ul><li><strong>期望状态</strong>：对象 <code>spec</code> 描述你想要什么。</li><li><strong>观察状态</strong>：对象 <code>status</code> 描述控制器目前看到什么。</li><li><strong>收敛</strong>：控制器不断缩小两者差异，通常是最终一致而非瞬时完成。</li><li><strong>幂等</strong>：重复提交相同期望状态不应产生额外副作用。</li><li><strong>Level-triggered</strong>：控制器根据当前状态做决定，而非仅依赖某个事件恰好到达。</li></ul><p>因此，API 请求成功通常只表示对象已被接受，不等于应用已经 Ready。发布系统还必须等待条件：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=5m</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wait</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --for=condition=available</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=5m</span></span></code></pre></div><h2 id="api-请求链路" tabindex="-1">API 请求链路 <a class="header-anchor" href="#api-请求链路" aria-label="Permalink to &quot;API 请求链路&quot;">​</a></h2><p>一个典型写请求经过：</p><ol><li>客户端从 kubeconfig 获取 API 地址、身份和 TLS 参数。</li><li>API Server 完成 TLS，并进行认证，得到用户与组。</li><li>鉴权器判断该身份能否对资源执行 verb。</li><li>Mutating Admission 修改或补全请求。</li><li>对象默认值填充、字段和版本校验。</li><li>Validating Admission 接受或拒绝请求。</li><li>API Server 持久化到 etcd，并返回对象。</li><li>Watch 客户端和控制器收到变化，异步处理。</li></ol><p>只读 List/Get 也经过认证和鉴权；部分准入插件只处理写请求。Webhook 失效策略、超时和网络故障可能阻塞集群写入，因此准入组件本身必须高可用且有明确 <code>failurePolicy</code>。</p><h2 id="api-group、version-与-resource" tabindex="-1">API Group、Version 与 Resource <a class="header-anchor" href="#api-group、version-与-resource" aria-label="Permalink to &quot;API Group、Version 与 Resource&quot;">​</a></h2><p>REST 路径示例：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/v1/namespaces/demo/pods/web</span></span>
<span class="line"><span>/apis/apps/v1/namespaces/demo/deployments/web</span></span></code></pre></div><ul><li>Core Group 使用 <code>/api/v1</code>，包括 Pod、Service、ConfigMap、Secret。</li><li>命名 API Group 使用 <code>/apis/&lt;group&gt;/&lt;version&gt;</code>，例如 <code>apps/v1</code>。</li><li><code>kind</code> 是对象类型，REST Resource 通常是小写复数。</li><li>一个资源可同时提供多个 API 版本；存储版本由 API Server 转换。</li></ul><p>发现当前集群实际支持的 API：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-versions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-resources</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sort-by=name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment.spec.strategy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /apis/apps/v1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span></span></code></pre></div><p>不要从旧博客复制已移除版本，如 <code>extensions/v1beta1</code> Ingress。以目标集群的发现结果和 <a href="https://kubernetes.io/docs/reference/generated/kubernetes-api/v1.36/" target="_blank" rel="noopener noreferrer">v1.36 API Reference</a> 为准。</p><h2 id="namespaced-与-cluster-scoped" tabindex="-1">Namespaced 与 Cluster-scoped <a class="header-anchor" href="#namespaced-与-cluster-scoped" aria-label="Permalink to &quot;Namespaced 与 Cluster-scoped&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-resources</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --namespaced=true</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-resources</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --namespaced=false</span></span></code></pre></div><p>Deployment、Pod、Service、ConfigMap 等属于命名空间；Node、Namespace、PersistentVolume、StorageClass、ClusterRole 等是集群级资源。命名空间是管理与授权边界，但不是天然的强安全边界；跨租户隔离还需要 RBAC、NetworkPolicy、Pod Security、资源配额和节点隔离。</p><h2 id="元数据与身份" tabindex="-1">元数据与身份 <a class="header-anchor" href="#元数据与身份" aria-label="Permalink to &quot;元数据与身份&quot;">​</a></h2><p>每个对象都有：</p><ul><li><code>name</code>：命名空间或集群范围内的名字。</li><li><code>namespace</code>：命名空间资源的作用域。</li><li><code>uid</code>：对象每次创建时生成的不可复用身份。</li><li><code>resourceVersion</code>：用于并发控制和 Watch，不是可排序业务版本。</li><li><code>generation</code>：期望状态 <code>spec</code> 变化时通常递增。</li><li><code>labels</code> / <code>annotations</code>：选择与非识别性元数据。</li><li><code>ownerReferences</code> / <code>finalizers</code>：垃圾回收和删除前清理机制。</li><li><code>managedFields</code>：Server-Side Apply 的字段所有权信息。</li></ul><p>控制器的 <code>status.observedGeneration</code> 若追上 <code>metadata.generation</code>，才说明它至少观察到了最新 spec；仍需结合 Ready/Available 条件判断成功。</p><h2 id="list、watch-与缓存" tabindex="-1">List、Watch 与缓存 <a class="header-anchor" href="#list、watch-与缓存" aria-label="Permalink to &quot;List、Watch 与缓存&quot;">​</a></h2><p>控制器通常先 List 建立本地缓存，再从某个 <code>resourceVersion</code> Watch 增量变化。Watch 可能断开或因版本过旧收到 <code>410 Gone</code>，客户端必须重新 List。写控制器时应使用官方 client-go informer/workqueue 模式，不要轮询整个集群。</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch-only</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-watch-events</span></span></code></pre></div><p>大集群查询要使用标签/字段选择器减少返回量；<code>kubectl get pods -A -o yaml</code> 会给 API Server、网络和终端带来不必要负担。</p><h2 id="扩展-kubernetes" tabindex="-1">扩展 Kubernetes <a class="header-anchor" href="#扩展-kubernetes" aria-label="Permalink to &quot;扩展 Kubernetes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>用途</th><th>风险</th></tr></thead><tbody><tr><td>CRD</td><td>添加自定义 API 资源</td><td>Schema、转换、版本兼容和删除保护</td></tr><tr><td>Operator/Controller</td><td>为自定义资源实现控制循环</td><td>权限过大、热循环、幂等与升级</td></tr><tr><td>Admission Webhook / Policy</td><td>校验或修改写请求</td><td>延迟、可用性和错误拒绝全局写入</td></tr><tr><td>API Aggregation</td><td>聚合独立 API Server</td><td>证书、发现与可用性更复杂</td></tr><tr><td>Scheduler Plugin</td><td>自定义调度行为</td><td>影响集群放置结果和升级兼容</td></tr></tbody></table><p>扩展前先问：是否能用内置对象、CEL 准入策略或现有成熟控制器解决？自定义 API 一旦被业务依赖，就需要像公共 API 一样维护版本和迁移。</p><h2 id="高可用边界" tabindex="-1">高可用边界 <a class="header-anchor" href="#高可用边界" aria-label="Permalink to &quot;高可用边界&quot;">​</a></h2><p>控制面多副本不自动等于业务高可用：</p><ul><li>API Server 可水平扩展；controller-manager 和 scheduler 通常多副本 Leader Election。</li><li>etcd 通常部署 3 或 5 个成员；跨高延迟地域扩展会降低写入性能和稳定性。</li><li>工作负载要跨节点和故障域放置，配置 PDB、拓扑分布与足够容量。</li><li>DNS、CNI、CSI、Ingress/Gateway、证书和镜像仓库也是关键依赖。</li><li>数据面在控制面短暂不可用时可能继续转发已有流量，但无法可靠调度、扩缩容或更新。</li></ul><p>官方组件说明见 <a href="https://kubernetes.io/docs/concepts/overview/components/" target="_blank" rel="noopener noreferrer">Kubernetes Components</a>。</p>`,41)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
